def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def best_step_toward(src, target):
        sx, sy = src
        tx, ty = target
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position"), (0, 0))
    opp_pos = pos(observation.get("opponent_position"), self_pos)

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)
    if not isinstance(gw, int):
        gw = 0
    if not isinstance(gh, int):
        gh = 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return best_step_toward(self_pos, opp_pos)

        corners = []
        if gw > 0 and gh > 0:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = corners[0]
        best_score = -1
        for c in corners:
            score = manhattan(c, opp_pos)
            if score > best_score:
                best_score = score
                target = c
        return best_step_toward(self_pos, target)

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "targets"):
            items = observation.get(key) or []
            for item in items:
                p = pos(item)
                if p is not None:
                    candidates.append(p)
        if candidates:
            target = candidates[0]
            best_d = manhattan(self_pos, target)
            for p in candidates[1:]:
                d = manhattan(self_pos, p)
                if d < best_d:
                    best_d = d
                    target = p
            return best_step_toward(self_pos, target)
        return best_step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        target = None
        best_d = None
        for item in resources:
            p = pos(item)
            if p is None:
                continue
            d = manhattan(self_pos, p)
            if best_d is None or d < best_d:
                best_d = d
                target = p
        if target is not None:
            return best_step_toward(self_pos, target)

    return best_step_toward(self_pos, opp_pos)

